const item = $input.item.json;

const elec = item.single_register_electricity_tariffs?._H?.direct_debit_monthly;
const gas = item.single_register_gas_tariffs?._H?.direct_debit_monthly;

// Skip items with no electricity data for North West region
if (!elec) {
  return { json: { skip: true } };
}

const isAgile = item.is_tracker || (item.code && item.code.startsWith('AGILE'));
const isEV = item.code && (item.code.includes('GO') || item.code.includes('INTELLI'));
const isCosy = item.code && item.code.includes('COSY');

let tariffType = 'standard';
if (isAgile) tariffType = 'dynamic';
else if (isEV) tariffType = 'EV';
else if (isCosy) tariffType = 'heat_pump';

return {
  json: {
    supplier: item.brand,
    plan_name: item.display_name,
    code: item.code,
    type: tariffType,
    is_variable: item.is_variable,
    is_green: item.is_green,
    is_tracker: item.is_tracker,
    term_months: item.term ?? null,
    exit_fee_gbp: (elec.exit_fees_inc_vat ?? 0) / 100,
    elec_unit_rate_p: elec.standard_unit_rate_inc_vat ?? null,
    elec_unit_rate_note: isAgile ? 'Dynamic pricing - varies every 30 min with wholesale market' : null,
    elec_standing_charge_p: elec.standing_charge_inc_vat ?? null,
    gas_unit_rate_p: gas ? (gas.standard_unit_rate_inc_vat ?? null) : null,
    gas_standing_charge_p: gas ? (gas.standing_charge_inc_vat ?? null) : null,
    fetched_at: new Date().toISOString()
  }
};

const items = $input.all().map(i => i.json);

return {
  json: {
    tariff_data: JSON.stringify(items, null, 2)
  }
};

const html = $input.item.json.data;

// Extract electricity unit rate
const elecMatch = html.match(/electricity.*?([\d.]+)\s*pence per kilowatt/i);
const elecRate = elecMatch ? parseFloat(elecMatch[1]) : null;

// Extract electricity standing charge
const elecSCMatch = html.match(/standing charge is ([\d.]+) pence per day.*electricity/i);
const elecSC = elecSCMatch ? parseFloat(elecSCMatch[1]) : null;

// Extract gas unit rate
const gasMatch = html.match(/gas.*?([\d.]+)\s*pence per kilowatt/i);
const gasRate = gasMatch ? parseFloat(gasMatch[1]) : null;

// Extract gas standing charge
const gasSCMatch = html.match(/standing charge is ([\d.]+) pence per day.*gas/i);
const gasSC = gasSCMatch ? parseFloat(gasSCMatch[1]) : null;

// Extract annual cap figure
const annualMatch = html.match(/£([\d,]+) per year/i);
const annualCap = annualMatch ? annualMatch[1] : null;

return {
  json: {
    supplier: 'OFGEM_PRICE_CAP',
    plan_name: 'Price Cap Benchmark (SVT)',
    code: 'OFGEM-CAP-Q2-2026',
    type: 'price_cap_benchmark',
    is_variable: true,
    is_green: false,
    is_tracker: false,
    term_months: 3,
    exit_fee_gbp: 0,
    elec_unit_rate_p: elecRate,
    elec_standing_charge_p: elecSC,
    gas_unit_rate_p: gasRate,
    gas_standing_charge_p: gasSC,
    annual_cap_gbp: annualCap,
    note: 'National average cap rates — Big 6 SVTs charged at or near these levels',
    fetched_at: new Date().toISOString()
  }
};
